def test_a_config_section_names_a_path_or_a_file_url(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.delenv("CALDAV_URL", raising=False)
    calendars = tmp_path / "calendars"
    calendars.mkdir()
    single = tmp_path / "with space" / "home.ics"
    single.parent.mkdir()
    config = tmp_path / "calendar.json"
    config.write_text(
        json.dumps({"todo": {"url": str(calendars)}, "home": {"kind": "files", "url": "file://" + quote(str(single))}})
    )
    workspace = Workspace.from_config(config, section="todo")
    [backend] = workspace.backends
    assert isinstance(backend, FilesBackend)
    assert (backend.layout, backend.path) == ("root", calendars)
    [home] = (Workspace.from_config(config, section="home")).backends
    assert isinstance(home, FilesBackend)
    assert (home.layout, home.path) == ("file", single)


