def test_a_collection_without_events_has_nowhere_to_log_time(tmp_path: Path) -> None:
    backend = Backend.open(str(tmp_path))
    tasks = backend.create_collection("tasks", components=[Component.TASK])
    both = backend.create_collection("both", components=[Component.TASK, Component.EVENT])
    assert tasks.capabilities.level(Feature.TIME_LOG) is Support.UNSUPPORTED
    assert "time_log_collection" in (tasks.capabilities[Feature.TIME_LOG].note or "")
    assert both.capabilities.level(Feature.TIME_LOG) is Support.FULL
